import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

export function attachFlyControls(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  // Use configurable free controls so Shift can be a pure speed modifier.
  // Replace the default down keys to avoid Shift moving the camera down.
  // Space rises, PageDown sinks, and left/right Shift triples movement speed.
  const detach = attachConfigurableFreeControl(camera, canvas, scene, {
    upKeys: ["Space"],
    downKeys: ["PageDown"],
    fastKeys: ["ShiftLeft", "ShiftRight"],
    fastMultiplier: 3,
  });

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    detach();
  };
}
```

I created `app/src/fly-controls.ts` using `attachConfigurableFreeControl` with `Space` as the only up key, `PageDown` as the only down key, and `ShiftLeft`/`ShiftRight` as speed-only fast keys with a multiplier of 3, returning an idempotent detach function. I was not sure whether `PageUp` should also remain as an up key, so I followed the requested Space-only behavior.
